    pub async fn add_user_id(mut self, delta: i64) -> anyhow::Result<u64> {
        struct AtomicTerminal {
            delta: i64,
        }
        impl<'repo, 'ctx> roze_orm::Operation<FriendshipQuery<'repo, 'ctx>, u64, anyhow::Error>
            for AtomicTerminal
        {
            fn call<'call>(
                &'call self,
                query: FriendshipQuery<'repo, 'ctx>,
            ) -> roze_orm::OperationFuture<'call, u64, anyhow::Error>
            where
                FriendshipQuery<'repo, 'ctx>: 'call,
                u64: 'call,
                anyhow::Error: 'call,
            {
                let delta = self.delta.clone();
                Box::pin(query.add_user_id_unintercepted(delta))
            }
        }
        let interceptors = std::mem::take(&mut self.atomic_interceptors);
        roze_orm::execute_chain(&AtomicTerminal { delta }, &interceptors, self).await
    }

    #[allow(clippy::clone_on_copy)]
    async fn add_user_id_unintercepted(self, delta: i64) -> anyhow::Result<u64> {
        let db = self.repo.write_db()?;
        let mut update = Entity::update_many()
            .col_expr(Column::UserId, Expr::col(Column::UserId).add(delta.clone()));
        for predicate in &self.predicates {
            update = update.filter(Self::predicate_condition(predicate));
        }
        let result = update.exec(&db).await?;
        Ok(result.rows_affected)
    }

