    #[allow(clippy::clone_on_copy)]
    pub async fn add_user_id(mut self, delta: i64) -> anyhow::Result<u64> {
        struct AtomicTerminal {
            delta: i64,
        }
        impl<'repo, 'ctx> roze_orm::Operation<FriendshipUpdateMany<'repo, 'ctx>, u64, anyhow::Error>
            for AtomicTerminal
        {
            fn call<'call>(
                &'call self,
                mutation: FriendshipUpdateMany<'repo, 'ctx>,
            ) -> roze_orm::OperationFuture<'call, u64, anyhow::Error>
            where
                FriendshipUpdateMany<'repo, 'ctx>: 'call,
                u64: 'call,
                anyhow::Error: 'call,
            {
                let delta = self.delta.clone();
                Box::pin(mutation.add_user_id_unhooked(delta))
            }
        }
        let hooks = std::mem::take(&mut self.atomic_hooks);
        roze_orm::execute_chain(&AtomicTerminal { delta }, &hooks, self).await
    }

    #[allow(clippy::clone_on_copy)]
    async fn add_user_id_unhooked(self, delta: i64) -> anyhow::Result<u64> {
        let mut query = self.repo.query();
        for predicate in self.predicates {
            query = query.where_(predicate);
        }
        query.add_user_id(delta).await
    }

